import{_ as o,o as t,c,ag as a}from"./chunks/framework.D5hoimZQ.js";const m=JSON.parse('{"title":"科学日报 · 2026-10-09（材料与能源）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/materials/science-daily-2026-10-09.md","filePath":"topics/materials/science-daily-2026-10-09.md"}'),i={name:"topics/materials/science-daily-2026-10-09.md"};function r(s,e,n,l,d,p){return t(),c("div",null,[...e[0]||(e[0]=[a('<h1 id="科学日报-·-2026-10-09-材料与能源" tabindex="-1">科学日报 · 2026-10-09（材料与能源） <a class="header-anchor" href="#科学日报-·-2026-10-09-材料与能源" aria-label="Permalink to &quot;科学日报 · 2026-10-09（材料与能源）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-09.md</code> — 第32期</p></blockquote><hr><h2 id="用挥发性共晶调控钙钛矿结晶-逼近太阳能电池效率极限-science" tabindex="-1">用挥发性共晶调控钙钛矿结晶，逼近太阳能电池效率极限（Science） <a class="header-anchor" href="#用挥发性共晶调控钙钛矿结晶-逼近太阳能电池效率极限-science" aria-label="Permalink to &quot;用挥发性共晶调控钙钛矿结晶，逼近太阳能电池效率极限（Science）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-09.md</code> ｜ DOI: 10.1126/science.aeb4554</p></blockquote><ul><li>问题：卤化物钙钛矿薄膜的<strong>辐射效率</strong>是逼近太阳能电池性能理论极限的关键。</li><li>方法：利用 <strong>ZnBr₂ 与 MACl（甲基氯化铵）添加剂之间的共晶相互作用</strong>来调控钙钛矿结晶。纳米探针 X 射线显微显示：退火时<strong>晶界处共晶发生局部熔融</strong>，降低晶粒内结构缺陷密度，同时<strong>卤素分布更均匀、锌向晶界偏析</strong>。</li><li>结果：薄膜具高光致发光量子产率、长载流子衰减时间、低表面复合速度；电池效率 <strong>26.5%（认证 25.9%）</strong>，&gt;15 cm² 微型组件 <strong>23.9%</strong>；空穴传输层小面积电池在 <strong>85°C 连续运行 1400 小时</strong>后保持初始 24.1% 的 <strong>85.8%</strong>；同一策略作 LED 达 <strong>26.1% EQE</strong>。</li><li>意义：一条可同时提升电池<strong>效率与稳定性</strong>的结晶工程路线，并嫁接到发光器件（LED）。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/materials/index.md</code> ｜ 第32期 科学板块</p></blockquote><p>关键词：钙钛矿、共晶、结晶调控、ZnBr₂、MACl、晶界熔融、光致发光量子产率、载流子寿命、25.9% 认证效率、稳定性、LED 关联：<code>topics/materials/science-daily-2026-10-08.md</code>（前一日：7 eV 超宽带隙半导体——同属&quot;用材料工程逼近器件极限&quot;）、<code>topics/materials/2026-q3-breakthroughs.md</code>（电池主线：钠离子等）、<code>topics/wind-energy/</code>（可再生能源器件侧的对照）</p>',9)])])}const u=o(i,[["render",r]]);export{m as __pageData,u as default};
